-- Fresh AppDatabase v12; schema only, no user rows.
BEGIN;
CREATE TABLE "local_owners" ("id" TEXT NOT NULL, "firebase_uid" TEXT NULL UNIQUE, "account_state" TEXT NOT NULL DEFAULT 'localGuest', "created_at_utc_ms" INTEGER NOT NULL CHECK (created_at_utc_ms >= 0), "upgraded_at_utc_ms" INTEGER NULL, "is_active" INTEGER NOT NULL DEFAULT 1 CHECK ("is_active" IN (0, 1)), PRIMARY KEY ("id"));
CREATE TABLE "model_downloads" ("id" TEXT NOT NULL, "model_version" TEXT NOT NULL, "source_url" TEXT NOT NULL, "expected_checksum" TEXT NOT NULL, "expected_bytes" INTEGER NOT NULL, "downloaded_bytes" INTEGER NOT NULL DEFAULT 0, "retry_count" INTEGER NOT NULL DEFAULT 0, "state" TEXT NOT NULL DEFAULT 'notStarted', "local_path" TEXT NULL, "failure_code" TEXT NULL, "updated_at_utc_ms" INTEGER NOT NULL, PRIMARY KEY ("id"), UNIQUE ("model_version"));
CREATE TABLE "quest_definition_revisions" ("quest_id" TEXT NOT NULL, "catalog_version" INTEGER NOT NULL, "definition_digest" TEXT NOT NULL, "canonical_definition" TEXT NOT NULL, PRIMARY KEY ("quest_id", "catalog_version"), UNIQUE ("quest_id", "catalog_version", "definition_digest"));
CREATE TABLE "quest_definitions" ("quest_id" TEXT NOT NULL, "catalog_version" INTEGER NOT NULL, "title" TEXT NOT NULL, "description" TEXT NOT NULL, "type" TEXT NOT NULL, "objectives_json" TEXT NOT NULL, "reward_json" TEXT NOT NULL, "expires_in_ms" INTEGER NULL, "tags_json" TEXT NOT NULL DEFAULT '[]', PRIMARY KEY ("quest_id"));
CREATE TABLE "runtime_flags" ("key" TEXT NOT NULL, "bool_value" INTEGER NOT NULL CHECK ("bool_value" IN (0, 1)), "source" TEXT NOT NULL DEFAULT 'local', "updated_at_utc_ms" INTEGER NOT NULL, "expires_at_utc_ms" INTEGER NULL, PRIMARY KEY ("key"));
CREATE TABLE "achievement_unlocks" ("id" TEXT NOT NULL, "owner_id" TEXT NOT NULL REFERENCES local_owners (id), "achievement_id" TEXT NOT NULL, "definition_version" INTEGER NOT NULL, "source_event_id" TEXT NOT NULL, "unlocked_at_utc_ms" INTEGER NOT NULL, PRIMARY KEY ("id"), UNIQUE ("owner_id", "achievement_id", "definition_version"));
CREATE TABLE "association_records" ("id" TEXT NOT NULL, "owner_id" TEXT NOT NULL REFERENCES local_owners (id), "word_key" TEXT NOT NULL, "type" TEXT NOT NULL, "content" TEXT NOT NULL, "created_at_utc_ms" INTEGER NOT NULL, PRIMARY KEY ("id"), UNIQUE ("owner_id", "word_key", "type"));
CREATE TABLE "associative_memory_states" ("id" TEXT NOT NULL, "owner_id" TEXT NOT NULL REFERENCES local_owners (id), "word_key" TEXT NOT NULL, "stability" REAL NOT NULL DEFAULT 1.0, "difficulty" REAL NOT NULL DEFAULT 5.0, "cue_dependency" REAL NOT NULL DEFAULT 0.0, "lapse_count" INTEGER NOT NULL DEFAULT 0, "last_reviewed_at_utc_ms" INTEGER NULL, "next_due_at_utc_ms" INTEGER NOT NULL, "algorithm_version" TEXT NOT NULL, PRIMARY KEY ("id"), UNIQUE ("owner_id", "word_key"));
CREATE TABLE "equipped_reward_items" ("id" TEXT NOT NULL, "owner_id" TEXT NOT NULL REFERENCES local_owners (id), "slot" TEXT NOT NULL, "item_id" TEXT NOT NULL, "equipped_at_utc_ms" INTEGER NOT NULL, PRIMARY KEY ("id"), UNIQUE ("owner_id", "slot"));
CREATE TABLE "events_v2" ("event_id" TEXT NOT NULL, "event_type" TEXT NOT NULL, "event_version" INTEGER NOT NULL, "occurred_at_utc" INTEGER NOT NULL, "recorded_at_utc" INTEGER NOT NULL, "actor_identity" TEXT NOT NULL, "owner_id" TEXT NOT NULL REFERENCES local_owners (id), "tenant_context_json" TEXT NULL, "aggregate_type" TEXT NOT NULL, "aggregate_id" TEXT NOT NULL, "correlation_id" TEXT NULL, "causation_id" TEXT NULL, "idempotency_key" TEXT NOT NULL, "consent_context_json" TEXT NOT NULL, "experiment_context_json" TEXT NULL, "content_revision" TEXT NULL, "policy_version" TEXT NULL, "app_version" TEXT NOT NULL, "build_id" TEXT NOT NULL, "provider_provenance_json" TEXT NULL, "privacy_classification" TEXT NOT NULL, "payload_json" TEXT NOT NULL, PRIMARY KEY ("event_id"), UNIQUE ("owner_id", "idempotency_key"));
CREATE TABLE "learning_day_log" ("id" TEXT NOT NULL, "owner_id" TEXT NOT NULL REFERENCES local_owners (id), "learning_day" TEXT NOT NULL, "first_session_at_utc_ms" INTEGER NOT NULL, PRIMARY KEY ("id"), UNIQUE ("owner_id", "learning_day"));
CREATE TABLE "learning_preferences" ("owner_id" TEXT NOT NULL REFERENCES local_owners (id), "onboarding_state" TEXT NOT NULL DEFAULT 'unset', "purpose" TEXT NULL, "planned_minutes" INTEGER NULL, "learning_method" TEXT NULL, "goal_civil_date" TEXT NULL, "goal_state" TEXT NOT NULL DEFAULT 'unset', "updated_at_utc_ms" INTEGER NOT NULL, PRIMARY KEY ("owner_id"), CHECK (planned_minutes IS NULL OR planned_minutes > 0), CHECK (onboarding_state IN ('unset', 'skipped', 'completed')), CHECK (goal_state IN ('unset', 'active', 'closed')), CHECK (goal_state <> 'active' OR goal_civil_date IS NOT NULL));
CREATE TABLE "learning_sessions" ("id" TEXT NOT NULL, "owner_id" TEXT NOT NULL REFERENCES local_owners (id), "activity_type" TEXT NOT NULL, "state" TEXT NOT NULL, "started_at_utc_ms" INTEGER NOT NULL, "ended_at_utc_ms" INTEGER NULL, "correct_count" INTEGER NOT NULL DEFAULT 0, "wrong_count" INTEGER NOT NULL DEFAULT 0, "score" INTEGER NULL, "app_version" TEXT NOT NULL, "build_id" TEXT NOT NULL, "question_plan_json" TEXT NULL, "continuation_json" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "local_content_reports" ("id" TEXT NOT NULL, "owner_id" TEXT NOT NULL REFERENCES local_owners (id), "source_kind" TEXT NOT NULL, "source_id" TEXT NOT NULL, "source_revision" INTEGER NOT NULL, "spelling" TEXT NOT NULL, "meaning" TEXT NOT NULL, "sentence" TEXT NULL, "reason" TEXT NOT NULL, "created_at_utc_ms" INTEGER NOT NULL, PRIMARY KEY ("id"), CHECK (source_revision > 0));
CREATE TABLE "outbox_operations" ("operation_id" TEXT NOT NULL, "owner_id" TEXT NOT NULL REFERENCES local_owners (id), "entity_type" TEXT NOT NULL, "entity_id" TEXT NOT NULL, "operation_kind" TEXT NOT NULL, "payload_version" INTEGER NOT NULL DEFAULT 1, "base_revision" INTEGER NOT NULL DEFAULT 0, "state" TEXT NOT NULL DEFAULT 'pending', "attempt_count" INTEGER NOT NULL DEFAULT 0, "next_attempt_at_utc_ms" INTEGER NULL, "lease_token" TEXT NULL, "lease_expires_at_utc_ms" INTEGER NULL, "last_attempt_at_utc_ms" INTEGER NULL, "created_at_utc_ms" INTEGER NOT NULL, "acknowledged_at_utc_ms" INTEGER NULL, "failure_code" TEXT NULL, PRIMARY KEY ("operation_id"));
CREATE TABLE "owner_calendar_epochs" ("rule_id" TEXT NOT NULL, "owner_id" TEXT NOT NULL REFERENCES local_owners (id), "origin_owner_id" TEXT NOT NULL, "effective_utc_us" INTEGER NOT NULL, "expires_utc_us" INTEGER NULL, "iana_id" TEXT NOT NULL, "tzdb_revision" TEXT NOT NULL, "is_selected" INTEGER NOT NULL CHECK ("is_selected" IN (0, 1)), PRIMARY KEY ("rule_id"), UNIQUE ("origin_owner_id", "effective_utc_us"), CHECK (expires_utc_us IS NULL OR expires_utc_us > effective_utc_us));
CREATE TABLE "points_ledger_entries" ("id" TEXT NOT NULL, "owner_id" TEXT NOT NULL REFERENCES local_owners (id), "idempotency_key" TEXT NOT NULL, "entry_type" TEXT NOT NULL, "amount" INTEGER NOT NULL, "source_event_id" TEXT NULL, "occurred_at_utc_ms" INTEGER NOT NULL, PRIMARY KEY ("id"), UNIQUE ("owner_id", "idempotency_key"));
CREATE TABLE "quest_instances" ("instance_id" TEXT NOT NULL, "quest_id" TEXT NOT NULL REFERENCES quest_definitions (quest_id), "owner_id" TEXT NOT NULL REFERENCES local_owners (id), "catalog_version" INTEGER NOT NULL, "assigned_at_utc_ms" INTEGER NOT NULL, "state" TEXT NOT NULL, "completed_at_utc_ms" INTEGER NULL, "expired_at_utc_ms" INTEGER NULL, "origin_owner_id" TEXT NULL, "period_key" TEXT NULL, "calendar_rule_id" TEXT NULL, "civil_label" TEXT NULL, "segments_json" TEXT NULL, "definition_digest" TEXT NULL, "canonical_instance_id" TEXT NULL REFERENCES quest_instances (instance_id), "record_kind" TEXT NOT NULL DEFAULT 'legacy', PRIMARY KEY ("instance_id"), FOREIGN KEY (quest_id, catalog_version, definition_digest) REFERENCES quest_definition_revisions (quest_id, catalog_version, definition_digest), CHECK ((record_kind = 'legacy' AND origin_owner_id IS NULL AND period_key IS NULL AND calendar_rule_id IS NULL AND civil_label IS NULL AND segments_json IS NULL AND definition_digest IS NULL AND canonical_instance_id IS NULL) OR (record_kind IN ('canonical', 'alias', 'conflict') AND COALESCE(origin_owner_id, '') <> '' AND COALESCE(period_key, '') <> '' AND COALESCE(calendar_rule_id, '') <> '' AND COALESCE(civil_label, '') <> '' AND COALESCE(segments_json, '') <> '' AND COALESCE(definition_digest, '') <> '' AND ((record_kind = 'alias' AND canonical_instance_id IS NOT NULL AND canonical_instance_id <> instance_id) OR (record_kind <> 'alias' AND canonical_instance_id IS NULL)))));
CREATE TABLE "reading_events" ("id" TEXT NOT NULL, "owner_id" TEXT NOT NULL REFERENCES local_owners (id), "document_id" TEXT NOT NULL, "document_revision" INTEGER NOT NULL DEFAULT 1, "event_type" TEXT NOT NULL, "position" INTEGER NULL, "occurred_at_utc_ms" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "reading_progress_entries" ("id" TEXT NOT NULL, "owner_id" TEXT NOT NULL REFERENCES local_owners (id), "document_id" TEXT NOT NULL, "document_revision" INTEGER NOT NULL DEFAULT 1, "last_position" INTEGER NOT NULL DEFAULT 0, "is_completed" INTEGER NOT NULL DEFAULT 0 CHECK ("is_completed" IN (0, 1)), "updated_at_utc_ms" INTEGER NOT NULL, PRIMARY KEY ("id"), UNIQUE ("owner_id", "document_id", "document_revision"));
CREATE TABLE "research_consents" ("id" TEXT NOT NULL, "owner_id" TEXT NOT NULL REFERENCES local_owners (id), "consent_version" INTEGER NOT NULL, "consent_state" TEXT NOT NULL, "decided_at_utc_ms" INTEGER NOT NULL, "withdrawn_at_utc_ms" INTEGER NULL, PRIMARY KEY ("id"), UNIQUE ("owner_id", "consent_version"));
CREATE TABLE "reward_transactions" ("id" TEXT NOT NULL, "owner_id" TEXT NOT NULL REFERENCES local_owners (id), "idempotency_key" TEXT NOT NULL, "transaction_type" TEXT NOT NULL, "amount" INTEGER NOT NULL, "item_id" TEXT NULL, "catalog_version" INTEGER NOT NULL, "source_event_id" TEXT NULL, "occurred_at_utc_ms" INTEGER NOT NULL, PRIMARY KEY ("id"), UNIQUE ("owner_id", "idempotency_key"));
CREATE TABLE "streak_baselines" ("origin_owner_id" TEXT NOT NULL, "owner_id" TEXT NOT NULL REFERENCES local_owners (id), "cutoff_utc_ms" INTEGER NOT NULL, "current_streak_days" INTEGER NOT NULL, "longest_streak_days" INTEGER NOT NULL, "freeze_count" INTEGER NOT NULL, "last_learned_at_utc_ms" INTEGER NULL, "updated_at_utc_ms" INTEGER NOT NULL, "controls_continuity" INTEGER NOT NULL CHECK ("controls_continuity" IN (0, 1)), PRIMARY KEY ("origin_owner_id"));
CREATE TABLE "streak_states" ("owner_id" TEXT NOT NULL REFERENCES local_owners (id), "current_streak_days" INTEGER NOT NULL DEFAULT 0, "longest_streak_days" INTEGER NOT NULL DEFAULT 0, "freeze_count" INTEGER NOT NULL DEFAULT 0, "last_learned_at_utc_ms" INTEGER NULL, "updated_at_utc_ms" INTEGER NOT NULL, PRIMARY KEY ("owner_id"));
CREATE TABLE "streak_token_adjustments" ("id" TEXT NOT NULL, "owner_id" TEXT NOT NULL REFERENCES local_owners (id), "origin_owner_id" TEXT NOT NULL, "command_id" TEXT NOT NULL, "occurred_at_utc_ms" INTEGER NOT NULL, "kind" TEXT NOT NULL, "delta" INTEGER NOT NULL, "protected_day" TEXT NULL, PRIMARY KEY ("id"), UNIQUE ("origin_owner_id", "command_id"), CHECK ((kind = 'grant' AND delta > 0 AND protected_day IS NULL) OR (kind = 'manualDebit' AND delta = -1 AND protected_day IS NULL) OR (kind = 'autoProtect' AND delta = -1 AND COALESCE(protected_day, '') <> '')));
CREATE TABLE "sync_checkpoints" ("id" TEXT NOT NULL, "owner_id" TEXT NOT NULL REFERENCES local_owners (id), "collection_name" TEXT NOT NULL, "server_cursor" TEXT NULL, "last_success_at_utc_ms" INTEGER NULL, PRIMARY KEY ("id"), UNIQUE ("owner_id", "collection_name"));
CREATE TABLE "sync_conflicts" ("id" TEXT NOT NULL, "owner_id" TEXT NOT NULL REFERENCES local_owners (id), "entity_type" TEXT NOT NULL, "entity_id" TEXT NOT NULL, "local_revision" INTEGER NOT NULL, "cloud_revision" INTEGER NOT NULL, "resolution_policy" TEXT NOT NULL, "outcome" TEXT NOT NULL, "local_snapshot_json" TEXT NULL, "cloud_snapshot_json" TEXT NULL, "resolved_at_utc_ms" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "vocabulary_categories" ("id" TEXT NOT NULL, "owner_id" TEXT NOT NULL REFERENCES local_owners (id), "name" TEXT NOT NULL, "normalized_name" TEXT NOT NULL, "sort_order" INTEGER NOT NULL DEFAULT 0, "local_revision" INTEGER NOT NULL DEFAULT 1, "cloud_revision" INTEGER NOT NULL DEFAULT 0, "last_acknowledged_at_utc_ms" INTEGER NULL, "server_updated_at_utc_ms" INTEGER NULL, "is_deleted" INTEGER NOT NULL DEFAULT 0 CHECK ("is_deleted" IN (0, 1)), "created_at_utc_ms" INTEGER NOT NULL, "updated_at_utc_ms" INTEGER NOT NULL, PRIMARY KEY ("id"), UNIQUE ("owner_id", "normalized_name"));
CREATE TABLE "focus_sessions" ("id" TEXT NOT NULL, "owner_id" TEXT NOT NULL REFERENCES local_owners (id), "origin_owner_id" TEXT NOT NULL, "target_ms" INTEGER NOT NULL, "started_at_utc_ms" INTEGER NOT NULL, "start_rule_id" TEXT NULL REFERENCES owner_calendar_epochs (rule_id), "start_civil_week" TEXT NULL, "state" TEXT NOT NULL, "revision" INTEGER NOT NULL DEFAULT 1, "spans_json" TEXT NOT NULL, "ended_at_utc_ms" INTEGER NULL, PRIMARY KEY ("id"), CHECK (target_ms > 0), CHECK (revision >= 1), CHECK (length(spans_json) > 0), CHECK ((start_rule_id IS NULL AND start_civil_week IS NULL) OR (start_rule_id IS NOT NULL AND start_civil_week IS NOT NULL)), CHECK (state IN ('running', 'paused', 'completed', 'interrupted')), CHECK ((state IN ('running', 'paused') AND ended_at_utc_ms IS NULL) OR (state = 'completed' AND ended_at_utc_ms IS NOT NULL) OR state = 'interrupted'));
CREATE TABLE "owned_reward_items" ("id" TEXT NOT NULL, "owner_id" TEXT NOT NULL REFERENCES local_owners (id), "item_id" TEXT NOT NULL, "catalog_version" INTEGER NOT NULL, "acquired_by_transaction_id" TEXT NOT NULL REFERENCES reward_transactions (id), "acquired_at_utc_ms" INTEGER NOT NULL, PRIMARY KEY ("id"), UNIQUE ("owner_id", "item_id"));
CREATE TABLE "quest_claim_receipts" ("id" TEXT NOT NULL, "owner_id" TEXT NOT NULL REFERENCES local_owners (id), "origin_owner_id" TEXT NOT NULL, "instance_id" TEXT NOT NULL REFERENCES quest_instances (instance_id), "issued_at_utc_ms" INTEGER NOT NULL, "completed_at_utc_ms" INTEGER NOT NULL, "xp_amount" INTEGER NOT NULL, "evidence_json" TEXT NOT NULL, PRIMARY KEY ("id"), UNIQUE ("instance_id"), CHECK (xp_amount > 0 AND length(evidence_json) > 0));
CREATE TABLE "quest_objective_progress" ("id" TEXT NOT NULL, "instance_id" TEXT NOT NULL REFERENCES quest_instances (instance_id) ON DELETE CASCADE, "objective_id" TEXT NOT NULL, "current_count" INTEGER NOT NULL DEFAULT 0, "target_count" INTEGER NOT NULL, "source_event_ids_json" TEXT NOT NULL DEFAULT '[]', PRIMARY KEY ("id"), UNIQUE ("instance_id", "objective_id"));
CREATE TABLE "vocabulary_imports" ("id" TEXT NOT NULL, "owner_id" TEXT NOT NULL REFERENCES local_owners (id), "category_id" TEXT NOT NULL REFERENCES vocabulary_categories (id), "source_type" TEXT NOT NULL, "source_name" TEXT NOT NULL, "source_hash" TEXT NOT NULL, "status" TEXT NOT NULL, "accepted_count" INTEGER NOT NULL DEFAULT 0, "duplicate_count" INTEGER NOT NULL DEFAULT 0, "rejected_count" INTEGER NOT NULL DEFAULT 0, "created_at_utc_ms" INTEGER NOT NULL, "completed_at_utc_ms" INTEGER NULL, PRIMARY KEY ("id"), UNIQUE ("owner_id", "category_id", "source_hash"));
CREATE TABLE "vocabulary_words" ("id" TEXT NOT NULL, "owner_id" TEXT NOT NULL REFERENCES local_owners (id), "category_id" TEXT NOT NULL REFERENCES vocabulary_categories (id), "spelling" TEXT NOT NULL, "normalized_spelling" TEXT NOT NULL, "meaning" TEXT NOT NULL, "normalized_meaning" TEXT NOT NULL, "part_of_speech" TEXT NOT NULL, "cefr_level" TEXT NULL, "source" TEXT NOT NULL DEFAULT 'manual', "is_global" INTEGER NOT NULL DEFAULT 0 CHECK ("is_global" IN (0, 1)), "local_revision" INTEGER NOT NULL DEFAULT 1, "cloud_revision" INTEGER NOT NULL DEFAULT 0, "last_acknowledged_at_utc_ms" INTEGER NULL, "server_updated_at_utc_ms" INTEGER NULL, "is_deleted" INTEGER NOT NULL DEFAULT 0 CHECK ("is_deleted" IN (0, 1)), "created_at_utc_ms" INTEGER NOT NULL, "updated_at_utc_ms" INTEGER NOT NULL, "is_bookmarked" INTEGER NOT NULL DEFAULT 0 CHECK ("is_bookmarked" IN (0, 1)), PRIMARY KEY ("id"), UNIQUE ("owner_id", "category_id", "normalized_spelling", "normalized_meaning"));
CREATE TABLE "answer_attempts" ("id" TEXT NOT NULL, "owner_id" TEXT NOT NULL REFERENCES local_owners (id), "session_id" TEXT NOT NULL REFERENCES learning_sessions (id) ON DELETE CASCADE, "word_id" TEXT NOT NULL REFERENCES vocabulary_words (id), "prompt_mode" TEXT NOT NULL, "is_correct" INTEGER NOT NULL CHECK ("is_correct" IN (0, 1)), "response_time_ms" INTEGER NULL, "attempt_number" INTEGER NOT NULL, "occurred_at_utc_ms" INTEGER NOT NULL, "provider_provenance" TEXT NULL, "calendar_evidence" TEXT NULL, "quest_intent" TEXT NULL, "answer_evidence_json" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "srs_states" ("id" TEXT NOT NULL, "owner_id" TEXT NOT NULL REFERENCES local_owners (id), "word_id" TEXT NOT NULL REFERENCES vocabulary_words (id), "stability" REAL NOT NULL DEFAULT 0.0, "difficulty" REAL NOT NULL DEFAULT 0.0, "interval_days" INTEGER NOT NULL DEFAULT 0, "repetitions" INTEGER NOT NULL DEFAULT 0, "lapses" INTEGER NOT NULL DEFAULT 0, "last_review_at_utc_ms" INTEGER NULL, "due_at_utc_ms" INTEGER NOT NULL, "algorithm_version" INTEGER NOT NULL, PRIMARY KEY ("id"), UNIQUE ("owner_id", "word_id"));
CREATE TABLE "vocabulary_import_rows" ("id" TEXT NOT NULL, "import_id" TEXT NOT NULL REFERENCES vocabulary_imports (id) ON DELETE CASCADE, "row_number" INTEGER NOT NULL, "payload_hash" TEXT NOT NULL, "status" TEXT NOT NULL, "failure_code" TEXT NULL, "word_id" TEXT NULL, PRIMARY KEY ("id"), UNIQUE ("import_id", "row_number"));
CREATE UNIQUE INDEX idx_calendar_selected_owner_effective ON owner_calendar_epochs(owner_id,effective_utc_us) WHERE is_selected=1;
CREATE INDEX idx_events_v2_owner_occurred ON events_v2(owner_id, occurred_at_utc);
CREATE UNIQUE INDEX idx_focus_open_owner ON focus_sessions(owner_id) WHERE state IN ('running','paused');
CREATE INDEX idx_focus_owner_start_week ON focus_sessions(owner_id,start_civil_week);
CREATE INDEX idx_learning_attempts_owner_time_id ON answer_attempts(owner_id,occurred_at_utc_ms,id);
CREATE INDEX idx_learning_attempts_owner_word_time ON answer_attempts(owner_id, word_id, occurred_at_utc_ms);
CREATE INDEX idx_learning_reading_owner_document ON reading_progress_entries(owner_id, document_id, document_revision);
CREATE INDEX idx_learning_sessions_owner_started ON learning_sessions(owner_id, started_at_utc_ms);
CREATE INDEX idx_learning_srs_owner_due ON srs_states(owner_id, due_at_utc_ms);
CREATE UNIQUE INDEX idx_quest_canonical_owner_period ON quest_instances(owner_id,period_key) WHERE record_kind='canonical';
CREATE UNIQUE INDEX idx_streak_auto_protection_origin_day ON streak_token_adjustments(origin_owner_id,protected_day) WHERE kind='autoProtect';
CREATE UNIQUE INDEX idx_streak_continuity_owner ON streak_baselines(owner_id) WHERE controls_continuity=1;
PRAGMA user_version = 12;
COMMIT;
